int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_sb_info *info = sb->s_fs_info;
    struct shmem_config temp_config;
    int error = 0;

    if (parse_shmem_options(data, &temp_config) < 0) {
        return -EINVAL;
    }

    mutex_lock(&info->lock);

    if (temp_config.max_blocks < info->max_blocks ||
        temp_config.max_inodes < info->max_inodes) {
        mutex_unlock(&info->lock);
        return -EINVAL;
    }

    if (temp_config.max_blocks > 0) {
        info->max_blocks = temp_config.max_blocks;
    }

    if (temp_config.max_inodes > 0) {
        info->max_inodes = temp_config.max_inodes;
    }

    if (temp_config.policy != NULL) {
        mpol_set(info->policy, temp_config.policy, 0);
    }

    mutex_unlock(&info->lock);

    return 0;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config new_config;
    int error = 0;

    if (parse_shmem_options(data, &new_config))
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (new_config.max_blocks < sb->s_blocks || new_config.max_inodes < sb->s_inodes) {
        spin_unlock(&sb->s_lock);
        return -EINVAL;
    }

    sb->s_max_blocks = new_config.max_blocks;
    sb->s_max_inodes = new_config.max_inodes;

    if (new_config.mpol != NULL) {
        mpol_put(sb->s_mpol);
        sb->s_mpol = mpol_get(new_config.mpol);
    }

    spin_unlock(&sb->s_lock);

    return 0;
}

